(async () => {
  const { env } = await import('node:process');
  const { accessSync, constants } = await import('node:fs');
  const inputPath = env.INPUT_PATH;
  const outputPath = env.OUTPUT_PATH;
  if (!inputPath) throw new Error('Missing INPUT_PATH env var');
  if (!outputPath) throw new Error('Missing OUTPUT_PATH env var');
  try { accessSync(inputPath, constants.R_OK); } catch { throw new Error('Input file not accessible'); }
  globalThis.inputPath = inputPath;
  globalThis.outputPath = outputPath;
})();

(async () => {
  const { createReadStream, createWriteStream } = await import('node:fs');
  const { Transform } = await import('node:stream');
  const { Yaml2json } = await import('@adius/yaml2json');
  const inputPath = globalThis.inputPath;
  const outputPath = globalThis.outputPath;
  const stringify = new Transform({
    writableObjectMode: true,
    transform(chunk, _encoding, done) {
      done(null, JSON.stringify(chunk) + '\n');
    }
  });
  await new Promise((resolve, reject) => {
    createReadStream(inputPath)
      .pipe(new Yaml2json())
      .pipe(stringify)
      .pipe(createWriteStream(outputPath))
      .on('finish', resolve)
      .on('error', reject);
  });
})();
